#!/usr/bin/env python3
"""
E11 — Controles não-ToS para a ablação causal da fonte dos marcadores.

Modos:
- otsu_edt: máximos locais do EDT da máscara Otsu;
- internal_medial: máximo do EDT em cada componente da máscara interna.

Os marcadores podem ser igualados ao número do BA-TOS por
--match-count-from. Não usa GT.
"""

from __future__ import annotations

import argparse
import itertools
import json
import math
import platform
import sys
from pathlib import Path

import numpy as np
import pandas as pd
import scipy
import skimage
import tifffile
from scipy import ndimage as ndi
from skimage.feature import peak_local_max
from skimage.filters import threshold_otsu


CONNECTIVITY_6 = ndi.generate_binary_structure(3, 1)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--image", type=Path, required=True)
    parser.add_argument(
        "--internal-source",
        type=Path,
        default=None,
    )
    parser.add_argument(
        "--mode",
        choices=("otsu_edt", "internal_medial"),
        required=True,
    )
    parser.add_argument("--out-dir", type=Path, required=True)
    parser.add_argument("--nms-radius", type=float, default=6.0)
    parser.add_argument(
        "--match-count-from",
        type=Path,
        default=None,
    )
    parser.add_argument(
        "--target-count",
        type=int,
        default=None,
    )
    # batos_v3 patch: hard-coded mask constants exposed (defaults = frozen values)
    parser.add_argument("--v3-min-component", type=int, default=500)
    parser.add_argument("--v3-closing-iterations", type=int, default=1)
    return parser.parse_args()


def read3d(path: Path, description: str) -> np.ndarray:
    if not path.is_file():
        raise FileNotFoundError(f"{description}: {path}")
    array = np.asarray(tifffile.imread(path))
    array = np.squeeze(array)
    if array.ndim == 4 and array.shape[-1] in (3, 4):
        array = array[..., 0]
    if array.ndim != 3:
        raise ValueError(
            f"{description} precisa ser 3D; shape={array.shape}"
        )
    return array


def normalize_image(image: np.ndarray) -> np.ndarray:
    work = image.astype(np.float32, copy=False)
    finite = np.isfinite(work)
    if not finite.any():
        raise ValueError("Imagem sem valores finitos.")
    values = work[finite]
    low, high = np.percentile(values, [1.0, 99.0])
    if high <= low:
        low = float(values.min())
        high = float(values.max())
    if high <= low:
        return np.zeros(work.shape, dtype=np.float32)
    result = np.clip((work - low) / (high - low), 0.0, 1.0)
    result[~finite] = 0.0
    return result.astype(np.float32, copy=False)


def clean_bright_otsu_mask(
    image_norm: np.ndarray,
    min_component: int = 500,
    closing_iterations: int = 1,
) -> tuple[np.ndarray, float]:
    threshold = float(threshold_otsu(image_norm))
    mask = image_norm > threshold
    mask = ndi.binary_closing(
        mask,
        structure=CONNECTIVITY_6,
        iterations=int(closing_iterations),
    )
    mask = ndi.binary_fill_holes(mask)
    labels, count = ndi.label(mask, structure=CONNECTIVITY_6)
    if count == 0:
        raise RuntimeError("A máscara Otsu bright ficou vazia.")
    sizes = np.bincount(labels.ravel())
    keep = sizes >= int(min_component)
    keep[0] = False
    return keep[labels], threshold


def marker_count(path: Path) -> int:
    raw = read3d(path, "Match-count marker")
    _, count = ndi.label(raw > 0, structure=CONNECTIVITY_6)
    if count <= 0:
        raise ValueError("O marcador de referência está vazio.")
    return int(count)


def greedy_nms(
    frame: pd.DataFrame,
    radius: float,
) -> pd.DataFrame:
    if frame.empty:
        return frame.copy()
    if radius <= 0:
        raise ValueError("nms-radius precisa ser positivo.")

    points = frame[["z", "y", "x"]].to_numpy(dtype=np.int64)
    physical = points.astype(float)
    priority = frame["priority"].to_numpy(dtype=float)
    source_index = frame["source_index"].to_numpy(dtype=np.int64)
    order = np.lexsort(
        (
            points[:, 2],
            points[:, 1],
            points[:, 0],
            source_index,
            -priority,
        )
    )

    radius_squared = float(radius * radius)
    grid: dict[tuple[int, int, int], list[int]] = {}
    kept: list[int] = []
    offsets = list(itertools.product((-1, 0, 1), repeat=3))

    for index in order:
        point = physical[index]
        cell = tuple(
            int(math.floor(value / radius))
            for value in point
        )
        reject = False
        for offset in offsets:
            neighbor = (
                cell[0] + offset[0],
                cell[1] + offset[1],
                cell[2] + offset[2],
            )
            for previous in grid.get(neighbor, []):
                delta = point - physical[previous]
                if float(np.dot(delta, delta)) < radius_squared:
                    reject = True
                    break
            if reject:
                break
        if reject:
            continue
        kept.append(int(index))
        grid.setdefault(cell, []).append(int(index))

    return frame.iloc[kept].copy().reset_index(drop=True)


def marker_volume(
    frame: pd.DataFrame,
    shape: tuple[int, int, int],
) -> np.ndarray:
    dtype = (
        np.uint16
        if len(frame) <= np.iinfo(np.uint16).max
        else np.uint32
    )
    result = np.zeros(shape, dtype=dtype)
    for label, point in enumerate(
        frame[["z", "y", "x"]].to_numpy(dtype=np.int64),
        start=1,
    ):
        result[tuple(point)] = label
    return result


def otsu_edt_candidates(
    mask: np.ndarray,
) -> pd.DataFrame:
    edt = ndi.distance_transform_edt(mask)
    coords = peak_local_max(
        edt,
        min_distance=1,
        threshold_abs=0.0,
        exclude_border=False,
        num_peaks=np.inf,
        labels=mask.astype(np.uint8),
        p_norm=2,
    )
    if coords.size == 0:
        raise RuntimeError("Nenhum máximo local EDT encontrado.")
    values = edt[tuple(coords[:, axis] for axis in range(3))]
    return pd.DataFrame(
        {
            "source_index": np.arange(len(coords), dtype=np.int64),
            "z": coords[:, 0],
            "y": coords[:, 1],
            "x": coords[:, 2],
            "priority": values,
            "control_mode": "otsu_edt",
        }
    )


def internal_medial_candidates(
    internal: np.ndarray,
) -> pd.DataFrame:
    labels, count = ndi.label(internal, structure=CONNECTIVITY_6)
    if count == 0:
        raise RuntimeError("A máscara internal source está vazia.")
    edt = ndi.distance_transform_edt(internal)
    indices = np.arange(1, count + 1, dtype=np.int32)
    positions = ndi.maximum_position(
        edt,
        labels=labels,
        index=indices,
    )
    coords = np.asarray(positions, dtype=np.int64)
    values = edt[tuple(coords[:, axis] for axis in range(3))]
    valid = np.isfinite(values) & (values > 0)
    coords = coords[valid]
    values = values[valid]
    return pd.DataFrame(
        {
            "source_index": indices[valid].astype(np.int64),
            "z": coords[:, 0],
            "y": coords[:, 1],
            "x": coords[:, 2],
            "priority": values,
            "control_mode": "internal_medial",
        }
    )


def main() -> int:
    args = parse_args()
    image_path = args.image.expanduser().resolve()
    out_dir = args.out_dir.expanduser().resolve()
    out_dir.mkdir(parents=True, exist_ok=True)

    image = read3d(image_path, "Image")
    image_norm = normalize_image(image)
    otsu_mask, otsu_threshold = clean_bright_otsu_mask(image_norm, args.v3_min_component, args.v3_closing_iterations)

    if args.target_count is not None and args.match_count_from is not None:
        raise ValueError(
            "Use somente --target-count ou --match-count-from."
        )
    if args.match_count_from is not None:
        target_count = marker_count(
            args.match_count_from.expanduser().resolve()
        )
    else:
        target_count = args.target_count

    if args.mode == "otsu_edt":
        candidates = otsu_edt_candidates(otsu_mask)
    else:
        if args.internal_source is None:
            raise ValueError(
                "--internal-source é obrigatório em internal_medial."
            )
        internal = read3d(
            args.internal_source.expanduser().resolve(),
            "Internal source",
        ) > 0
        if internal.shape != image.shape:
            raise ValueError(
                f"Shape internal={internal.shape} image={image.shape}"
            )
        candidates = internal_medial_candidates(internal)

    before_nms = int(len(candidates))
    selected = greedy_nms(
        candidates,
        radius=float(args.nms_radius),
    )
    after_nms = int(len(selected))

    selected = selected.sort_values(
        ["priority", "z", "y", "x", "source_index"],
        ascending=[False, True, True, True, True],
    ).reset_index(drop=True)

    if target_count is not None:
        if target_count <= 0:
            raise ValueError("target-count precisa ser positivo.")
        if len(selected) < target_count:
            raise RuntimeError(
                f"{args.mode}: somente {len(selected)} marcadores "
                f"após NMS; target={target_count}."
            )
        selected = selected.iloc[:target_count].copy().reset_index(drop=True)

    selected["marker_id"] = np.arange(
        1,
        len(selected) + 1,
        dtype=np.int64,
    )
    marker_path = out_dir / "markers_uint16.tif"
    csv_path = out_dir / "markers.csv"
    tifffile.imwrite(
        marker_path,
        marker_volume(selected, image.shape),
        compression="zlib",
    )
    selected.to_csv(csv_path, index=False)

    summary = {
        "experiment": "E11_control_markers",
        "gt_used": False,
        "mode": args.mode,
        "nms_radius": float(args.nms_radius),
        "candidate_count_before_nms": before_nms,
        "marker_count_after_nms": after_nms,
        "target_count": (
            int(target_count) if target_count is not None else None
        ),
        "final_marker_count": int(len(selected)),
        "otsu_threshold": float(otsu_threshold),
        "otsu_mask_fraction": float(otsu_mask.mean()),
        "python": platform.python_version(),
        "numpy": np.__version__,
        "scipy": scipy.__version__,
        "skimage": skimage.__version__,
        "marker_tiff": str(marker_path),
        "marker_csv": str(csv_path),
    }
    (out_dir / "control_config.json").write_text(
        json.dumps(summary, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )

    print("=" * 80)
    print("E11 — CONTROL MARKER CONSTRUCTION")
    print("=" * 80)
    for key, value in summary.items():
        print(f"{key:36s}: {value}")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(
            f"[E11][ERRO] {type(exc).__name__}: {exc}",
            file=sys.stderr,
        )
        raise
